}

#define WIN_DRAW_LINE_WIDTH 1.0f

inline Color GadgetRadioGetEnabledColor(GameWindow *g) { return g->enabledColor(0); }
inline Color GadgetRadioGetEnabledBorderColor(GameWindow *g) { return g->enabledBorderColor(0); }
inline Color GadgetRadioGetEnabledCheckedBoxColor(GameWindow *g) { return g->enabledColor(2); }
